# 过滤出所有正数，保持原有顺序。


def collect_positive(values):
    out = []
    for v in values:
        if v <= 0:
            return out
        out.append(v)
    return out

verification_tests:
from target import collect_positive


def test_all_positive():
    assert collect_positive([1, 2, 3]) == [1, 2, 3]


def test_empty_values():
    assert collect_positive([]) == []


def test_invalid_in_the_middle():
    assert collect_positive([1, -2, 3]) == [1, 3]
